using Microsoft.AspNetCore.Builder;using Microsoft.AspNetCore.Http;using Microsoft.AspNetCore.Routing;using Mbb.Archive.BuildingBlocks.Presentation;using Mbb.Archive.Modules.Archive.Application.Records.Declare;using Mbb.Archive.Modules.Archive.Application.Records.Get;
namespace Mbb.Archive.Modules.Archive.Presentation;
public static class ArchiveEndpoints{public static IEndpointRouteBuilder MapArchiveEndpoints(this IEndpointRouteBuilder e){var g=e.MapGroup("/api/v1/archive").WithTags("Archive").RequireAuthorization();g.MapGet("/records/{id:guid}",async(Guid id,GetArchiveRecordQueryHandler h,CancellationToken ct)=>{var r=await h.Handle(new GetArchiveRecordQuery(id),ct);return r.IsFailure?ApiResults.Problem(r.Error):Results.Ok(r.Value);}).RequireAuthorization("permission:archive.records.read");g.MapPost("/records/{id:guid}/declare",async(Guid id,DeclareRequest req,DeclareArchiveRecordCommandHandler h,CancellationToken ct)=>{var r=await h.Handle(new DeclareArchiveRecordCommand(id,req.ClassificationCode,req.RetentionRuleCode),ct);return r.IsFailure?ApiResults.Problem(r.Error):Results.NoContent();}).RequireAuthorization("permission:archive.records.declare");return e;}private sealed record DeclareRequest(string ClassificationCode,string RetentionRuleCode);}
